import{_ as s,a0 as i,w as o,s as p,ao as u,I as r,x as e,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"Linux 有问必答：如何在Perl中捕捉并处理信号 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何在Perl中捕捉并处理信号 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何在Perl中捕捉并处理信号 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何在Perl中捕捉并处理信号 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140925 Linux FAQs with Answers--How to catch and handle a signal in Perl","title":"Linux 有问必答：如何在Perl中捕捉并处理信号","tag":"201410","desc":""},"relativePath":"201410/20140925 Linux FAQs with Answers--How to catch and handle a signal in Perl.md","filePath":"[post].md"}'),d={name:"201410/20140925 Linux FAQs with Answers--How to catch and handle a signal in Perl.md"};function m(T,t,x,h,g,f){const n=i("Link");return o(),p("div",null,[t[11]||(t[11]=u(`<h1 id="linux-有问必答-如何在perl中捕捉并处理信号" tabindex="-1">Linux 有问必答：如何在Perl中捕捉并处理信号 <a class="header-anchor" href="#linux-有问必答-如何在perl中捕捉并处理信号" aria-label="Permalink to “Linux 有问必答：如何在Perl中捕捉并处理信号”">​</a></h1><blockquote><p><strong>提问</strong>: 我需要通过使用Perl的自定义信号处理程序来处理一个中断信号。在一般情况下，我怎么在Perl程序中捕获并处理各种信号（如INT，TERM）？</p></blockquote><p>作为POSIX标准的异步通知机制，信号由操作系统发送给进程某个事件来通知它。当产生信号时，操作系统会中断目标程序的执行，并且该信号被发送到该程序的信号处理函数。可以定义和注册自己的信号处理程序或使用默认的信号处理程序。</p><p>在Perl中，信号可以被捕获，并由一个全局的%SIG哈希变量指定处理函数。这个%SIG哈希变量的键名是信号值，键值是对应的信号处理程序的引用。因此，如果你想为特定的信号定义自己的信号处理程序，你可以直接在%SIG中设置信号的哈希值。</p><p>下面是一个代码段来处理使用自定义信号处理程序中断（INT）和终止（TERM）的信号。</p><pre><code>$SIG{INT}  = \\&amp;signal_handler;
$SIG{TERM} = \\&amp;signal_handler;
 
sub signal_handler {
    print &quot;This is a custom signal handler\\n&quot;;
    die &quot;Caught a signal $!&quot;;
}
</code></pre><p><img src="https://farm4.staticflickr.com/3910/15141131060_f7958f20fb.jpg" alt=""></p><p>%SIG其他的可用的键值有&#39;IGNORE&#39;和&#39;DEFAULT&#39;。当所指定的键值是&#39;IGNORE&#39;（例如，$SIG{CHLD}=&#39;IGNORE&#39;）时，相应的信号将被忽略。指定&#39;DEFAULT&#39;的键值（例如，$SIG{HUP}=&#39;DEFAULT&#39;），意味着我们将使用一个（系统）默认的信号处理程序。</p><hr>`,9)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),a(n,{href:"http://ask.xmodulo.com/catch-handle-interrupt-signal-perl.html"},{default:l(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/catch-handle-interrupt-signal-perl.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:l(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:l(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:l(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const C=s(d,[["render",m]]);export{P as __pageData,C as default};
